import { Checkbox, Form, Input, Typography, Button, Modal } from "antd";
import { useState } from "react";
import Swal from "sweetalert2";


const { Title } = Typography;

export default function Carregister() {
  // 스타일 정의
  const styles = {
    container: {
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      padding: "20px",
      backgroundColor: "white",
      borderRadius: "5px",
      maxWidth: "700px",
      margin: "20px auto",
      height: "400px",
      marginTop: "150px"
    },
    carInput: {
      width: "350px",
      marginTop: "20px"
    },
    checkboxGrid: {
      display: "flex",
      gap: "42px",
      marginTop: "10px"
    },
    button: {
      marginTop: "40px"
    }
  };

  // 상태 정의
  const [carNumber, setCarNumber] = useState("");
  const [isExternal, setIsExternal] = useState(false);
  const [isElectric, setIsElectric] = useState(false);
  const [isDisabled, setIsDisabled] = useState(false);

  // 핸들러 정의
  const handleInputChange = (e) => {
    setCarNumber(e.target.value);
  };

  const handleCheckboxChange = (name, isChecked) => {
    switch (name) {
      case "external":
        setIsExternal(isChecked);
        break;
      case "electric":
        setIsElectric(isChecked);
        break;
      case "disabled":
        setIsDisabled(isChecked);
        break;
      default:
        break;
    }
  };

  const handleSubmit = async () => {
    const payload = {
      carNumber,
      isExternal,
      isElectric,
      isDisabled
    };
    try {
      const response = await fetch("YOUR_SERVER_ENDPOINT", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(payload)
      });
      if (response.status === 200) {
        Swal.fire("Success!", "등록 완료!", "success");
      } else {
        const data = await response.json();
        Swal.fire("Error!", "등록 실패: " + (data.message || ""), "error");
      }
    } catch (error) {
      Swal.fire("Oops...", "서버와의 통신에 문제가 발생했습니다.", "error");
    }
  };

  return (
    <>
   <div style={styles.container}>
      <Title level={2}>차량 등록 페이지</Title>

      <div style={styles.carInput}>
        <Form.Item label="차량번호">
          <Input onChange={handleInputChange} />
        </Form.Item>
      </div>

      <div style={styles.checkboxGrid}>
        <Checkbox
          onChange={(e) => handleCheckboxChange("external", e.target.checked)}
        >
          외부차량
        </Checkbox>
        <Checkbox
          onChange={(e) => handleCheckboxChange("electric", e.target.checked)}
        >
          전기차량
        </Checkbox>
        <Checkbox
          onChange={(e) => handleCheckboxChange("disabled", e.target.checked)}
        >
          장애차량
        </Checkbox>
      </div>
    

      <div style={styles.button}>
        <Button
          type="primary"
          onClick={handleSubmit}
          size={"large"}
          style={{ width: "200px" }}
        >
          제출
        </Button>
      </div>
    </div>
    </>
  );
}
