import React, { useState, useEffect } from "react";
import { Menu, Dropdown, Avatar, Button, Drawer, Modal } from "antd";
import { UserOutlined, MenuOutlined } from "@ant-design/icons";
import { Link } from "react-router-dom";
import Carregister from "./carregister.js";

const Navbar = () => {
  const [visible, setVisible] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 600);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const showModal = () => {
    setIsModalOpen(true);
  };


  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth <= 600) {
        setIsMobile(true);
      } else {
        setIsMobile(false);
      }
    };

    window.addEventListener("resize", handleResize);

    return () => {
      // Cleanup the event listener on component unmount
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  const profileMenu = (
    <Menu>
      <Menu.Item key="0">
        <a href="#" style={{ textDecoration: "none" }}>
          Profile
        </a>
      </Menu.Item>
      <Menu.Item key="1">
        <a href="#" style={{ textDecoration: "none" }}>
          Settings
        </a>
      </Menu.Item>
      <Menu.Divider />
      <Menu.Item key="3">
        <Link to="/" style={{ textDecoration: "none" }}>
          Logout
        </Link>
      </Menu.Item>
    </Menu>
  );

  const HorizontalMenu = ({ mode }) => (
    <Menu mode={mode}>
      <Menu.Item key="home">
        <Link to="/main" style={{ textDecoration: "none" }}>
          Home
        </Link>
      </Menu.Item>
      <Menu.Item key="carManagement" onClick={showModal}>
        차량등록
      </Menu.Item>
      <Menu.SubMenu key="community" title="커뮤니티">
        <Menu.Item key="announcement">
          <Link to="/noticeboard" style={{ textDecoration: "none" }}>
            공지사항
          </Link>
        </Menu.Item>
        <Menu.Item key="vote">투표</Menu.Item>
        <Menu.Item key="complaint">
          <Link to="/request" style={{ textDecoration: "none" }}>
            민원
          </Link>
        </Menu.Item>
      </Menu.SubMenu>
      <Menu.SubMenu key="convenience" title="편의기능">
        <Menu.Item key="news">최신뉴스</Menu.Item>
        <Menu.Item key="disasterMsg">재난 문자</Menu.Item>
        <Menu.Item key="publicTransport">주변 대중교통 정보</Menu.Item>
        <Menu.Item key="hospitalPharmacy">주변 병의원/약국정보</Menu.Item>
      </Menu.SubMenu>
    </Menu>
  );

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        borderBottom: "3px solid #f0f0f0",
      }}
    >
      <a
        href="/main"
        style={{
          padding: "0 16px",
          fontSize: "20px",
          fontWeight: "bold",
          color: "#1890ff",
          textDecoration: "none",
        }}
      >
        Eureka
      </a>
      {!isMobile && <HorizontalMenu mode={"horizontal"} />}
      <div>
        {isMobile && (
          <Button
            icon={<MenuOutlined />}
            onClick={() => setVisible(true)}
            style={{ border: "none" }}
          />
        )}
        <Dropdown overlay={profileMenu} trigger={isMobile ? ["click"] : ["hover"]}>
          <Button type="text" icon={<UserOutlined />} />
        </Dropdown>
      </div>
      <Drawer
        title="Menu"
        placement="right"
        closable={false}
        onClose={() => setVisible(false)}
        visible={visible}
        bodyStyle={{ padding: 0 }}
        width="80%"
      >
        <HorizontalMenu mode={"inline"} />
      </Drawer>
      <Modal
        visible={isModalOpen}
        onCancel={() => setIsModalOpen(false)}
        footer={null}
      >
        <Carregister />
      </Modal>
    </div>
  );
};

export default Navbar;

