import React from "react";
import { Button, Typography, Table, Card } from "antd";
import { EditOutlined } from "@ant-design/icons"; // 아이콘을 위한 import
import NavBar from "./navbar";

// 예시 데이터
const data = [
  { key: 1, title: "첫번째 공지", author: "관리자", date: "2023-07-31" },
  { key: 2, title: "두번째 공지", author: "관리자", date: "2023-07-31" },
];

const columns = [
  {
    title: "No",
    dataIndex: "key",
    key: "key",
  },
  {
    title: "제목",
    dataIndex: "title",
    key: "title",
  },
  {
    title: "작성자",
    dataIndex: "author",
    key: "author",
  },
  {
    title: "작성일",
    dataIndex: "date",
    key: "date",
  },
];

const Noticeboard = () => {
  return (
    <>
      <NavBar />
      <div
        style={{ padding: "24px", background: "#f4f4f4", minHeight: "100vh" }}
      >
        <Typography.Title
          level={2}
          style={{
            textAlign: "center",
            marginBottom: "24px",
            color: "#4a4a4a",
          }}
        >
          공지사항
        </Typography.Title>

        <Card
          bordered
          style={{
            boxShadow: "0px 0px 20px rgba(0, 0, 0, 0.08)", // 그림자 효과 추가
            display: "flex", // Flexbox 설정
            flexDirection: "column", // 세로 방향으로 항목 정렬
          }}
        >
          <Table
            dataSource={data}
            columns={columns}
            pagination={false}
            // 테이블 헤더 스타일 조정
            bordered
          />
          <Button
            type="primary"
            icon={<EditOutlined />} // 글쓰기 아이콘 추가
            style={{ alignSelf: "flex-end" }} // 버튼을 왼쪽으로 정렬
          >
            글쓰기
          </Button>
        </Card>
      </div>
    </>
  );
};

export default Noticeboard;
